VALUES
  (207, true, '207|||עמותת בני ובנות משפחה של מתמודדי/ות נפש בישראל. מטרת העמותה היא לפעול למען המתמודדים ולמען משפחותיהם למימוש ולהרחבת זכויות, לטיפול מיטבי, להכלה ולשיקום בקהילה ולהסברה בקרב מקבלי החלטות, בקרב הממסד ובקרב הציבור.', '207|||עמותה של בני משפחה של מתמודדי נפש: מימוש זכויות, וסיוע ישיר למשפחות.', '{"org":"משפחות בריאות הנפש","svc":"עמותה של בני משפחה של מתמודדי נפש: מימוש זכויות, וסיוע ישיר למשפחות.","meeting":"","target":"בני משפחה של מתמודדי נפש","region":"כל הארץ","founded":"","cost":"","specialty":"","approaches":"","notes":"ת.ד. 65037, תל אביב.","web":"https://www.mishpachot.org/","phone":"058-7540054","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"mbhnoffice@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"whatsapp":"","whatsappLabel":""}'::jsonb, '{"org":"Mental Health Families","svc":"An organization of family members of people coping with mental illness: realizing rights, and direct help for families.","meeting":"","target":"Family members of people coping with mental illness","region":"Nationwide","founded":"","cost":"","specialty":"","approaches":"","notes":"P.O. Box 65037, Tel Aviv.","phone":"058-7540054","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"mbhnoffice@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":"","whatsapp":"","whatsappLabel":""}'::jsonb, '23.11.2026: נבדק מול https://www.mishpachot.org/. הוואטסאפ לא מופיע בדף. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (208, true, '208|||מנחה ומלווה משפחות למתמודדי נפש', '208|||ליווי למשפחות של מתמודדי נפש, וקורסים למלווים.', '{"org":"ענת רוסמן","svc":"ליווי למשפחות של מתמודדי נפש, וקורסים למלווים.","meeting":"","target":"","region":"קריית מוצקין","founded":"","cost":"","specialty":"","approaches":"","notes":"דרך עכו 49. הקורסים באתר אינם טיפול.","web":"https://anatrosman.co.il/","phone":"052-7817590","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"Anat.rossman@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Anat Rosman","svc":"Accompaniment for families of people coping with mental illness, and courses for companions.","meeting":"","target":"","region":"Kiryat Motzkin","founded":"","cost":"","specialty":"","approaches":"","notes":"49 Derech Akko. The courses on the site are not treatment.","phone":"052-7817590","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"Anat.rossman@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: דף הבית לא נפתח. הפרטים מעמוד התקנון באתר, שעודכן בדצמבר 2025. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (227, true, '227|||שירותים חברתיים לצעירים 18-27', '227|||ליווי אישי וסל מענים לצעירים ולצעירות במצבי סיכון. דרך המחלקה לשירותים חברתיים.', '{"org":"יתד (משרד הרווחה)","svc":"ליווי אישי וסל מענים לצעירים ולצעירות במצבי סיכון. דרך המחלקה לשירותים חברתיים.","meeting":"","target":"צעירים וצעירות 18–25","region":"כל הארץ","founded":"2016","cost":"משרד הרווחה","specialty":"","approaches":"","notes":"","web":"https://www.gov.il/he/pages/2016_dec2014","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"YATED@MOLSA.GOV.IL","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Yated (Ministry of Welfare)","svc":"Personal accompaniment and a basket of services for young men and women in situations of risk. Through the social services department.","meeting":"","target":"Young men and women, ages 18-25","region":"Nationwide","founded":"2016","cost":"The Ministry of Welfare","specialty":"","approaches":"","notes":"","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"YATED@MOLSA.GOV.IL","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול החלטת ממשלה 2014. הגיל הוא 18 עד 25 כולל, לא 18–27. רשימת העו״ס נשארת כרטיס נפרד. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (237, true, '237|||טיפול לבני זוג שאיבדו בן/בת במהלך שירות (מלחמה, תאונה, מחלה, התאבדות)', '237|||מעטפת שיקומית וליווי אישי לבנות ולבני זוג של חללי צה״ל. במפגש.', '{"org":"הותיר אחריו חבר.ה","svc":"מעטפת שיקומית וליווי אישי לבנות ולבני זוג של חללי צה״ל. במפגש.","meeting":"in_person","target":"בנות ובני זוג של חללי צה״ל","region":"כל הארץ","founded":"1998","cost":"בתמיכת משרד הביטחון","specialty":"","approaches":"","notes":"לכל אחד מוצמדת מלווה, חברה שכולה ותיקה.","web":"https://www.girlfriendsidf.org.il/","phone":"077-770-3166","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@gfidf.org.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Left a Partner Behind","svc":"A rehabilitation framework and personal accompaniment for partners of fallen IDF soldiers. At a meeting.","meeting":"in_person","target":"Partners of fallen IDF soldiers","region":"Nationwide","founded":"1998","cost":"With support from the Ministry of Defense","specialty":"","approaches":"","notes":"Each person is paired with a companion, a bereaved partner who has been in the organization longer.","phone":"077-770-3166","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@gfidf.org.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.girlfriendsidf.org.il/. 050-8298292 אינו באתר. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (238, true, '238|||טיפול קבוצתי/זוגי/פרטני לשכולים ואחים/יתומים/אלמנות', '238|||מימון טיפול נפשי, וליווי של עובד סוציאלי, למשפחות שכולות.', '{"org":"אגף משפחות, הנצחה ומורשת (משרד הביטחון)","svc":"מימון טיפול נפשי, וליווי של עובד סוציאלי, למשפחות שכולות.","meeting":"","target":"הורים שכולים, אלמנות ואלמנים, יתומים, אחים, ארוסים ואפוטרופוסים","region":"כל הארץ","founded":"","cost":"משרד הביטחון","specialty":"","approaches":"","notes":"פגישה שבועית, עד 3 שנים. יש גם קבוצות תמיכה. האישור לפני תחילת הטיפול.","web":"https://mishpahot-hantzaha.mod.gov.il/emotional-support","phone":"03-7776700","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Department of Families, Commemoration and Heritage (Ministry of Defense)","svc":"Funding for mental-health treatment, and accompaniment by a social worker, for bereaved families.","meeting":"","target":"Bereaved parents, widows and widowers, orphans, siblings, fiancés, and guardians","region":"Nationwide","founded":"","cost":"The Ministry of Defense","specialty":"","approaches":"","notes":"A weekly session, for up to 3 years. There are also support groups. Approval comes before treatment starts.","phone":"03-7776700","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://mishpahot-hantzaha.mod.gov.il/emotional-support ודף הטיפול הנפשי. הטלפון 03-7776700 הוא של היחידה לשירותים סוציאליים. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (239, true, '239|||טיפול פרטני, זוגי, משפחתי וייעוץ פסיכיאטרי', '239|||פסיכותרפיה לאובדן, לשכול ולטראומה. במכון.', '{"org":"מרכז אלה","svc":"פסיכותרפיה לאובדן, לשכול ולטראומה. במכון.","meeting":"in_person","target":"מי שחווה אובדן","region":"כל הארץ","founded":"1979","cost":"","specialty":"אובדן, שכול, טראומה","approaches":"טיפול פרטני, טיפול זוגי, טיפול משפחתי, טיפול קבוצתי","notes":"","web":"https://www.elah.org.il/","phone":"1-800-800-440","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@elah.org.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"whatsapp":"972506644000","whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"Elah Center","svc":"Psychotherapy for loss, bereavement, and trauma. At the institute.","meeting":"in_person","target":"People who have experienced a loss","region":"Nationwide","founded":"1979","cost":"","specialty":"Loss, bereavement, trauma","approaches":"Individual therapy, couples therapy, family therapy, group therapy","notes":"","phone":"1-800-800-440","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@elah.org.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":"","whatsapp":"972506644000","whatsappLabel":"WhatsApp"}'::jsonb, '23.11.2026: נבדק מול https://www.elah.org.il/. 03-6910921 ו-elah@elah.org.il אינם בדף הבית. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (241, true, '241|||טיפול משפחתי אינטנסיבי לילדים 6-18', '241|||טיפול נפשי אינטנסיבי קצר, כדי למנוע או לדחות אשפוז. במרכז, בבית החולים.', '{"org":"יחידה להתערבות במשבר — מרכז רפואי העמק (כללית)","svc":"טיפול נפשי אינטנסיבי קצר, כדי למנוע או לדחות אשפוז. במרכז, בבית החולים.","meeting":"in_person","target":"ילדים ובני נוער","region":"עפולה","founded":"","cost":"קופת החולים, עם טופס 17","specialty":"","approaches":"","notes":"לפחות 3 פגישות בשבוע, עד 6 שבועות. אחר כך הפניה להמשך טיפול בקהילה.","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/public-care/kids-and-teens/intervention-centers/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Crisis intervention unit, Emek Medical Center (Clalit)","svc":"Short, intensive mental-health treatment, to prevent or postpone hospitalization. At the center, in the hospital.","meeting":"in_person","target":"Children and youth","region":"Afula","founded":"","cost":"The health fund, with Form 17","specialty":"","approaches":"","notes":"At least 3 sessions a week, for up to 6 weeks. Afterwards, a referral for continued treatment in the community.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול דף מרכזי ההתערבות של משרד הבריאות מ-13 באוגוסט 2025. העמק בעפולה אחד המרכזים. אין עמוד נפרד של בית החולים, ו-ayol_clalit.org.il יורד. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (256, true, '256|||איתור, ליווי וטיפול בנוער וצעירים במצבי סיכון — בקהילה, ברחוב ובמרחב הדיגיטלי', '256|||איתור, ליווי וטיפול בנוער ובצעירים במצבי סיכון. בקהילה, ברחוב ובצ׳אט.', '{"org":"עמותת על\"ם","svc":"איתור, ליווי וטיפול בנוער ובצעירים במצבי סיכון. בקהילה, ברחוב ובצ׳אט.","meeting":"","target":"נוער וצעירים במצבי סיכון","region":"כל הארץ","founded":"","cost":"","specialty":"","approaches":"","notes":"הירקון 35, בני ברק.","web":"https://www.elem.org.il/","phone":"03-7686666","phoneLabel":"מטה","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"elem@elem.org.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"whatsapp":"972546786776","whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"Elem","svc":"Finding, accompanying, and treating youth and young adults in situations of risk. In the community, on the street, and in a chat.","meeting":"","target":"Youth and young adults in situations of risk","region":"Nationwide","founded":"","cost":"","specialty":"","approaches":"","notes":"35 HaYarkon St, Bnei Brak.","phone":"03-7686666","phoneLabel":"Headquarters","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"elem@elem.org.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":"","whatsapp":"972546786776","whatsappLabel":"WhatsApp"}'::jsonb, '23.11.2026: נבדק מול https://elem.org.il/. שעות הצ׳אט לא עולות לכרטיס. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (258, true, '258|||תנועת נוער משלבת לילדים עם ובלי צרכים מיוחדים — שילוב חברתי מלא ושוויוני', '258|||תנועת נוער משלבת, לילדים עם צרכים מיוחדים ולילדים בלי. בסניף.', '{"org":"כנפיים של קרמבו","svc":"תנועת נוער משלבת, לילדים עם צרכים מיוחדים ולילדים בלי. בסניף.","meeting":"in_person","target":"ילדים עם צרכים מיוחדים, ובני נוער חונכים","region":"כל הארץ","founded":"","cost":"","specialty":"","approaches":"","notes":"מפגש שבועי של כשלוש שעות, בחונכות אישית.","web":"https://www.krembo.org.il/","phone":"*8849","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Krembo Wings","svc":"An inclusive youth movement, for children with special needs and children without them. At a branch.","meeting":"in_person","target":"Children with special needs, and youth mentors","region":"Nationwide","founded":"","cost":"","specialty":"","approaches":"","notes":"A weekly meeting of about three hours, with personal mentoring.","phone":"*8849","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.krembo.org.il/. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (259, true, '259|||תנועת נוער וצעירים להט"ב — קבוצות חברתיות ותמיכה בעשרות יישובים', '259|||תנועת נוער וצעירים להט״ב, עם קבוצות שבועיות ומועדונים. במפגש.', '{"org":"איגי — ארגון הנוער הגאה","svc":"תנועת נוער וצעירים להט״ב, עם קבוצות שבועיות ומועדונים. במפגש.","meeting":"in_person","target":"נוער וצעירים להט״ב","region":"כל הארץ","founded":"2002","cost":"ללא תשלום","specialty":"","approaches":"","notes":"פעילות הנוער מכיתה ז׳ עד י״ב. יש קבוצות לקשת הטרנסית, לדוברי ערבית, לקשת הדתית ולקהילה האתיופית. אלנבי 43, תל אביב.","web":"https://igy.org.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"IGY, the LGBTQ youth organization","svc":"A youth and young-adult movement for LGBT people, with weekly groups and clubs. At a meeting.","meeting":"in_person","target":"LGBT youth and young adults","region":"Nationwide","founded":"2002","cost":"At no charge","specialty":"","approaches":"","notes":"Youth activity is from 7th grade to 12th grade. There are groups for trans people, Arabic speakers, religious people, and the Ethiopian community. 43 Allenby St, Tel Aviv.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://igy.org.il/. 03-5280698 אינו בעמוד. הניסוח אושר עם אצוות הנוער והמשפחות.'),
