  (289, true, '289|||רשת הוסטלים לנערות וצעירות במצבי סיכון — ראשון לציון; גישה מודעת טראומה', '289|||רשת הוסטלים לנערות ולצעירות במצבי סיכון. בשהייה בהוסטל.', '{"org":"בית משלך (חכמת נשים)","svc":"רשת הוסטלים לנערות ולצעירות במצבי סיכון. בשהייה בהוסטל.","meeting":"in_person","target":"נערות 13–18, צעירות 18–22, וצעירות וחיילות בודדות בלינה זמנית","region":"ראשון לציון","founded":"","cost":"המשרד לביטחון חברתי","specialty":"","approaches":"גישה מודעת טראומה","notes":"הפניה דרך המחלקה לשירותים חברתיים. נערות לחסות הנוער, וצעירות בדוח סוציאלי. המרפאה בכרטיס נפרד.","web":"https://wtc-anatgur.co.il/%D7%90%D7%95%D7%93%D7%95%D7%AA/%D7%91%D7%99%D7%AA-%D7%9E%D7%A9%D7%9C%D7%9A/","phone":"052-8511650","phoneLabel":"מור","phoneShowNumber":false,"phone2":"050-9155122","phoneLabel2":"שני","phoneShowNumber2":false,"phone3":"050-6223382","phoneLabel3":"ציפי","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"morh@slavpro.co.il","emailLabel":"מור","emailShowAddress":false,"email2":"shanis@slavpro.co.il","emailLabel2":"שני","emailShowAddress2":false,"email3":"tzipin@wtc-anatgur.co.il","emailLabel3":"ציפי","emailShowAddress3":false}'::jsonb, '{"org":"A Home of Your Own (Chochmat Nashim)","svc":"A network of hostels for girls and young women in situations of risk. While staying at the hostel.","meeting":"in_person","target":"Girls ages 13-18, young women ages 18-22, and young women and lone soldiers in temporary lodging","region":"Rishon LeZion","founded":"","cost":"The Ministry of Welfare and Social Security","specialty":"","approaches":"A trauma-informed approach","notes":"Referral is through the social services department. Girls are referred to youth protection, and young women with a social report. The clinic is on a separate card.","phone":"052-8511650","phoneLabel":"Mor","phone2":"050-9155122","phoneLabel2":"Shani","phone3":"050-6223382