  (308, true, '308|||רשימת מרכזי הייעוץ למשפחות בקהילה ובבתי החולים', '308|||ייעוץ, קבוצות תמיכה ומיצוי זכויות לבני משפחה של מתמודדי נפש. במרכז.', '{"org":"מרכזי ייעוץ למשפחות","svc":"ייעוץ, קבוצות תמיכה ומיצוי זכויות לבני משפחה של מתמודדי נפש. במרכז.","meeting":"in_person","target":"בני משפחה","region":"כל הארץ","founded":"","cost":"ללא עלות","specialty":"","approaches":"","notes":"אין צורך באישור סל שיקום.","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/rehabilitation/rehabilitation-basket/family-counseling-centers/","webLabel":"משרד הבריאות","web2":"https://www.gov.il/he/departments/dynamiccollectors/smtl-families-center","webLabel2":"רשימת המרכזים","phone":"*5400","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"08-6241010","phoneLabel2":"משרד הבריאות","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Family counseling centers","svc":"Counseling, support groups, and help realizing rights for family members of people coping with mental illness. At the center.","meeting":"in_person","target":"Family members","region":"Nationwide","founded":"","cost":"At no cost","specialty":"","approaches":"","notes":"No rehabilitation-basket approval is required.","phone":"*5400","phoneLabel":"Phone","phone2":"08-6241010","phoneLabel2":"Ministry of Health","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול דף משרד הבריאות מ-20 ביולי 2026. רשימת הטלפונים של בתי החולים אינה בעמוד הזה. קישור המאגר נשאר כרשימה. הניסוח אושר עם אצוות הנוער והמשפחות.'),
  (344, true, '344|||הכוונה לטיפול הפסיכולוגי המתאים לכם, סבסוד טיפולים, חוסן משפחתי. שינוי מפת ההתמודדות המשפחתית והקהילתית במצבי מצוקה אישיים ומשפחתיים.', '344|||הכוונה לטיפול פסיכולוגי, וסבסוד טיפולים משפחתיים, זוגיים ופרטניים.', '{"org":"חיים של טובה","svc":"הכוונה לטיפול פסיכולוגי, וסבסוד טיפולים משפחתיים, זוגיים ופרטניים.","meeting":"","target":"משפחות","region":"","founded":"2012","cost":"בסבסוד העמותה, או בתעריף מוזל","specialty":"דיכאון, חרדה, קשיים בזוגיות","approaches":"","notes":"","web":"https://hst.org.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"hst.org.il@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"whatsapp":"972585720770","whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"Chayim Shel Tova","svc":"Guidance toward psychological treatment, and a subsidy for family, couples, and individual treatment.","meeting":"","target":"Families","region":"","founded":"2012","cost":"Subsidized by the nonprofit, or at a reduced rate","specialty":"Depression, anxiety, difficulties in the relationship","approaches":"","notes":"","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"hst.org.il@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":"","whatsapp":"972585720770","whatsappLabel":"WhatsApp"}'::jsonb, '23.11.2026: נבדק מול https://hst.org.il/. הניסוח אושר עם אצוות הנוער והמשפחות.'),
