  (774, true, '774|||קבוצת תמיכה להורים למתמודדים עם OCD', '774|||קבוצת תמיכה והדרכה להורים למתמודדים עם OCD. בזום.', '{"org":"אור לב","svc":"קבוצת תמיכה והדרכה להורים למתמודדים עם OCD. בזום.","meeting":"online","target":"הורים למתמודדים עם OCD","region":"","founded":"","cost":"ההורה המשתתף","specialty":"OCD","approaches":"","notes":"מפגש של שעה עד שעה וחצי, עד 10 משתתפים. מחזור של 4 מפגשים, וההצטרפות בתחילת מחזור. המפגשים אינם מוקלטים. זו קבוצת תמיכה להורים, לא טיפול לילד. קבוצה למבוגרים בכרטיס נפרד.","web":"https://fighting-ocd.com/pereants-sec/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false,"whatsapp":"","whatsappLabel":""}'::jsonb, '{"org":"Or Lev","svc":"A support and guidance group for parents of people coping with OCD. On Zoom.","meeting":"online","target":"Parents of people coping with OCD","region":"","founded":"","cost":"The participating parent","specialty":"OCD","approaches":"","notes":"A meeting of an hour to an hour and a half, up to 10 participants. A cycle of 4 meetings, and joining is at the start of a cycle. The meetings are not recorded. This is a support group for parents, not treatment for the child. The group for adults is on a separate card.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":"","whatsapp":"","whatsappLabel":""}'::jsonb, '23.11.2026: נבדק מול https://fighting-ocd.com/pereants-sec/. 500 ש״ח, הטלפון, 